package org.ouyalibre.tv;
import android.app.*;import android.os.*;import android.content.*;import android.media.AudioManager;import android.view.*;import java.io.*;import java.net.*;import java.util.*;
/** Real local media playback; no fixture entries are added to the user's catalog. */
public final class Playback08Test extends Instrumentation {
 private boolean software=false;private ServerSocket server;private volatile boolean running=true;private int passed=0;
 private void check(boolean ok,String label){if(!ok)throw new AssertionError(label);passed++;Bundle b=new Bundle();b.putString("stream","PASS "+label+"\n");sendStatus(0,b);}
 public void onCreate(Bundle args){super.onCreate(args);software=args!=null&&"true".equals(args.getString("software"));start();}
 private Object field(Object object,String name)throws Exception{java.lang.reflect.Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
 public void onStart(){Bundle result=new Bundle();try{
  final File file=new File(software?"/sdcard/Download/OuyaLibre-prueba-MP2.ts":"/sdcard/Download/Prueba_OUYA_Movimiento_720p_H264.mp4");check(file.isFile()&&file.length()>100000,"Real local H264 video exists");server=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));Thread accept=new Thread(new Runnable(){public void run(){while(running)try{final Socket peer=server.accept();Thread worker=new Thread(new Runnable(){public void run(){try{peer.setSoTimeout(10000);BufferedReader in=new BufferedReader(new InputStreamReader(peer.getInputStream(),"US-ASCII"));String req=in.readLine(),line;long start=0;while((line=in.readLine())!=null&&line.length()>0)if(line.toLowerCase(Locale.US).startsWith("range: bytes=")){String value=line.substring(line.indexOf('=')+1).split("-")[0];start=Long.parseLong(value);}long length=file.length()-start;OutputStream out=peer.getOutputStream();String headers="HTTP/1.1 "+(start>0?"206 Partial Content":"200 OK")+"\r\nContent-Type: application/octet-stream\r\nContent-Length: "+length+"\r\nAccept-Ranges: bytes\r\n"+(start>0?"Content-Range: bytes "+start+"-"+(file.length()-1)+"/"+file.length()+"\r\n":"")+"Connection: close\r\n\r\n";out.write(headers.getBytes("US-ASCII"));if(!req.startsWith("HEAD")){RandomAccessFile data=new RandomAccessFile(file,"r");try{data.seek(start);byte[] buffer=new byte[32768];int n;while((n=data.read(buffer))!=-1)out.write(buffer,0,n);}finally{data.close();}}out.flush();}catch(Exception ignored){}finally{try{peer.close();}catch(Exception ignored){}}}});worker.setDaemon(true);worker.start();}catch(Exception ignored){}}});accept.setDaemon(true);accept.start();
  String url="http://127.0.0.1:"+server.getLocalPort()+(software?"/actual-local.ts":"/actual-local.mp4");Item item=new Item("Prueba local","actual-local","Prueba local H264","Archivo real local, sin Internet","",url);Intent intent=new Intent(getTargetContext(),PlayerActivity.class);intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);intent.putExtra("item",item.json().toString());intent.putExtra("stream",url);intent.putExtra("live",true);intent.putExtra("audioCompatible",software);final Activity activity=startActivitySync(intent);
  final EngineVideoView view=(EngineVideoView)field(activity,"video");long until=System.currentTimeMillis()+20000;while(view.getCurrentPosition()<300&&System.currentTimeMillis()<until)Thread.sleep(250);check(view.getCurrentPosition()>=300,"Bundled app plays actual local media without Internet");if(software){Thread.sleep(1000);org.videolan.libvlc.MediaPlayer engine=(org.videolan.libvlc.MediaPlayer)field(view,"player");check(engine!=null,"Software decoder runs inside OuyaLibre");org.videolan.libvlc.Media media=engine.getMedia();try{org.videolan.libvlc.Media.Stats stats=media.getStats();check(stats!=null&&stats.decodedAudio>0,"Real MPEG audio decoded in the bundled engine");check(stats.playedAbuffers>0,"Decoded audio buffers sent to the audio output");check(stats.displayedPictures>0,"Actual TS video frames displayed");result.putString("stream","TOTAL "+passed+" codec checks passed; audio buffers="+stats.playedAbuffers+", video frames="+stats.displayedPictures+"\n");}finally{media.release();}runOnMainSync(new Runnable(){public void run(){activity.finish();}});finish(0,result);return;}int before=view.getCurrentPosition();Thread.sleep(2500);check(view.getCurrentPosition()>before+1000,"Local H264 playback advances");Thread.sleep(3500);final View overlay=(View)field(activity,"overlay");check(overlay.getVisibility()==View.GONE,"Playback controls auto-hide");sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);Thread.sleep(150);check(overlay.getVisibility()==View.VISIBLE&&view.isPlaying(),"First controller key reveals controls without pausing");sendKeyDownUpSync(KeyEvent.KEYCODE_BUTTON_Y);Thread.sleep(150);check(overlay.getVisibility()==View.GONE,"Y hides playback controls");
  final AudioManager audio=(AudioManager)getTargetContext().getSystemService(Context.AUDIO_SERVICE);int original=audio.getStreamVolume(AudioManager.STREAM_MUSIC);try{if(original==0)audio.setStreamVolume(AudioManager.STREAM_MUSIC,1,0);int base=audio.getStreamVolume(AudioManager.STREAM_MUSIC);sendKeyDownUpSync(KeyEvent.KEYCODE_VOLUME_DOWN);Thread.sleep(150);check(audio.getStreamVolume(AudioManager.STREAM_MUSIC)==base-1,"Player volume down changes multimedia volume");sendKeyDownUpSync(KeyEvent.KEYCODE_VOLUME_UP);Thread.sleep(150);check(audio.getStreamVolume(AudioManager.STREAM_MUSIC)==base,"Player volume up restores multimedia volume");}finally{audio.setStreamVolume(AudioManager.STREAM_MUSIC,original,0);}
  runOnMainSync(new Runnable(){public void run(){activity.finish();}});result.putString("stream","TOTAL "+passed+" playback checks passed\n");finish(0,result);
 }catch(Throwable error){result.putString("stream","FAILED "+error+"\n");finish(1,result);}finally{running=false;if(server!=null)try{server.close();}catch(Exception ignored){}}}
}
